// ============================================
// VALIDATION INPUT
// ============================================

const input = $input.first().json;
const body = input.body || {};
const headers = input.headers || {};

// --- Extraction Project ID ---
const projectId = headers['x-project-id'] 
  || headers['X-Project-ID'] 
  || headers['X-Project-Id']
  || 'unknown';

// --- Validation des champs requis ---
if (!body.products || !Array.isArray(body.products) || body.products.length === 0) {
  return {
    error: true,
    error_code: 'MISSING_PRODUCTS',
    message: 'Le champ "products" est requis et doit etre un tableau non vide'
  };
}

// --- Validation de chaque produit ---
const validatedProducts = [];
for (let i = 0; i < body.products.length; i++) {
  const p = body.products[i];

  if (!p.name || typeof p.name !== 'string') {
    return {
      error: true,
      error_code: 'INVALID_PRODUCT',
      message: `Produit ${i}: le champ "name" est requis`
    };
  }

  if (typeof p.price_cents !== 'number' || p.price_cents < 0) {
    return {
      error: true,
      error_code: 'INVALID_PRODUCT',
      message: `Produit ${i}: le champ "price_cents" doit etre un nombre positif`
    };
  }

  validatedProducts.push({
    name: p.name,
    description: p.description || null,
    price_cents: p.price_cents,
    currency: p.currency || 'EUR',
    category: p.category || 'ingredient',
    image_url: p.image_url || null,
    brand: p.brand || null,
    seller: p.seller || null,
    seller_url: p.seller_url || null,
    source: p.source || 'web_search',
    source_query: p.source_query || null,
    reasoning_data: p.reasoning_data || null
  });
}

// --- Retour des donnees validees ---
return {
  error: false,
  data: {
    products: validatedProducts,
    project_id: projectId,
    products_count: validatedProducts.length
  }
};

// ============================================
// PREPARE SUCCESS RESPONSE
// ============================================

const apiResponse = $input.first().json;
const validationData = $('Validate Input').first().json;

// --- Check API errors ---
if (apiResponse.error || !apiResponse.success) {
  return {
    success: false,
    error: {
      code: apiResponse.error?.code || 'API_ERROR',
      message: apiResponse.error?.message || 'Erreur API',
      http_status: apiResponse.error?.http_status || 500
    }
  };
}

// --- Success response ---
return {
  success: true,
  products: apiResponse.products || [],
  created_count: apiResponse.created || validationData.data.products_count,
  project_id: validationData.data.project_id
};

// ============================================
// FORMAT ERROR RESPONSE (Validation)
// ============================================

const input = $input.first().json;

return {
  success: false,
  error: {
    code: input.error_code || 'VALIDATION_ERROR',
    message: input.message || 'Erreur de validation',
    http_status: 400
  }
};
